 function close(){dialog?.close();opener?.focus();}
 D.addEventListener('click',e=>{const b=e.target.closest('[data-ken-open]');if(!b)return;const n=route===root.location.hash&&notices[Number(b.dataset.kenOpen)];if(!n)return;opener=b;if(!dialog){dialog=D.createElement('dialog');dialog.className='ken-dialog';D.body.append(dialog);dialog.addEventListener('click',e=>{if(e.target===dialog||e.target.closest('[data-ken-close]'))close();});dialog.addEventListener('close',()=>opener?.focus());}dialog.innerHTML=`<header><div><small>LỊCH KIỂM TRA · ${E(n.program)}</small><h2 id="ken-title">${E(n.title)}</h2></div><button type="button" data-ken-close aria-label="Đóng lịch kiểm tra">×</button></header><div class="ken-body">${n.html}</div><footer><button type="button" data-ken-close>Đóng · Quay lại</button></footer>`;dialog.setAttribute('aria-labelledby','ken-title');dialog.showModal();});
